"use client";

import { useMemo } from "react";
import { TemplateItem } from "@/types/template";
import SignaturePreviewFrame from "@/components/studio/SignaturePreviewFrame";
import { generateTemplateHtml } from "@/lib/templates/renderTemplateHtml";

interface TemplateSignatureThumbnailProps {
  template: TemplateItem;
}

/**
 * Standardized template signature thumbnail rendering the exact, live signature HTML
 * generated by the template engine, scaled dynamically to fit the card preview area.
 * Standard Dimension: aspect-[350/174], min-h-[174px].
 */
export default function TemplateSignatureThumbnail({
  template,
}: TemplateSignatureThumbnailProps) {
  const { defaultData } = template;
  const preferTableBounds = [
    "corporate-elegant",
    "executive-corporate",
    "bold-block",
  ].includes(template.id);

  const previewHtml = useMemo(
    () => generateTemplateHtml(defaultData, { preview: true }),
    [defaultData]
  );

  return (
    <div className="flex h-full w-full items-center justify-center bg-white px-2 py-3 select-none sm:py-4">
      <div className="flex h-full w-full min-h-0 items-center justify-center">
        <SignaturePreviewFrame
          html={previewHtml}
          aspectRatio="350 / 174"
          fitPadding={0.92}
          preferTableBounds={preferTableBounds}
          className="h-full"
        />
      </div>
    </div>
  );
}
